INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('57763fc6-f48e-436d-a54f-f3431216a562', '0b8ddab7-b106-4873-bc4d-3987421d265d', 2, 'O Dever do Momento', NULL, '{"intro": "A ansiedade nasce de querer estar no futuro e negligenciar o presente.", "prayer": "Pe\u00e7a a gra\u00e7a da presen\u00e7a de esp\u00edrito.", "practice": "Fa\u00e7a a sua tarefa mais chata com total aten\u00e7\u00e3o e amor.", "reflection": "A santidade est\u00e1 em fazer bem o que se deve fazer agora.", "journal_prompt": "Voc\u00ea est\u00e1 presente no que est\u00e1 fazendo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;